import { Button, Group, Stack } from '@mantine/core';
import { FormErrors, isEmail, isNotEmpty, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { DirtyField } from './DirtyField';
import { ProfileValues } from './types';

export function DirtyFields() {
  const form = useForm<ProfileValues>({
    initialValues: {
      name: 'John Doe',
      email: 'john@mantine.dev',
      website: 'https://mantine.dev',
    },
    validate: {
      name: isNotEmpty('Name is required'),
      email: isEmail('Invalid email'),
    },
  });

  const dirty = form.useDirty();

  const handleSubmit = (values: ProfileValues) => {
    // Saved values become the new baseline for dirty checks
    form.setInitialValues(values);
    form.resetDirty(values);
    notifications.show({
      title: 'Profile saved',
      message: `${values.name} profile updated`,
    });
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack gap={5}>
        <DirtyField form={form} field="name" label="Name" placeholder="John Doe" />
        <DirtyField form={form} field="email" label="Email" placeholder="john@mantine.dev" />
        <DirtyField form={form} field="website" label="Website" placeholder="https://mantine.dev" />

        <Group justify="flex-end">
          {dirty && (
            <Button size="md" variant="default" onClick={form.reset}>
              Reset all
            </Button>
          )}

          <Button size="md" type="submit" disabled={!dirty}>
            Save changes
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

.root {
  padding: var(--mantine-spacing-xs);
  margin-inline: calc(var(--mantine-spacing-xs) * -1);
  transition: background-color 150ms ease;

  &[data-dirty] {
    background-color: color-mix(in srgb, var(--mantine-primary-color-light) 40%, transparent);
  }
}

import { ArrowCounterClockwiseIcon } from '@phosphor-icons/react';
import { ActionIcon, TextInput, TextInputProps } from '@mantine/core';
import { ProfileForm, ProfileValues } from './types';
import classes from './DirtyField.module.css';

interface DirtyFieldProps extends Omit<TextInputProps, 'label' | 'form'> {
  form: ProfileForm;
  field: keyof ProfileValues;
  label: string;
}

export function DirtyField({ form, field, label, ...others }: DirtyFieldProps) {
  const dirty = form.useDirty(field);

  return (
    <TextInput
      size="md"
      label={label}
      classNames={classes}
      mod={{ dirty }}
      rightSectionPointerEvents="all"
      rightSection={
        dirty && (
          <ActionIcon
            variant="subtle"
            color="gray"
            aria-label={`Reset ${label.toLowerCase()}`}
            onClick={() => form.resetField(field)}
          >
            <ArrowCounterClockwiseIcon size={16} />
          </ActionIcon>
        )
      }
      {...others}
      {...form.getInputProps(field)}
    />
  );
}

import { UseFormReturnType } from '@mantine/form';

export interface ProfileValues {
  name: string;
  email: string;
  website: string;
}

export type ProfileForm = UseFormReturnType<ProfileValues>;
